<script setup>
import {computed,reactive} from 'vue'
import {Button as UiButton} from './ui/button'
import {consoleAPI} from '../api'
import {label,stateLabel} from '../labels'
const props=defineProps({schema:Object,model:Object,readonly:Boolean,scope:Object,child:Boolean})
const links=reactive({})
const fields=computed(()=>props.schema.fields.filter(f=>!['Section Break','Column Break','Tab Break','HTML','Button','Password'].includes(f.fieldtype)))
async function options(field){if(field.fieldtype!=='Link')return;try{links[field.fieldname]=await consoleAPI('link_options',{doctype:field.options,search:props.model[field.fieldname]||'',farm:props.scope?.farm,company:props.scope?.company})}catch{links[field.fieldname]=[]}}
function add(field){const row={};for(const c of props.schema.tables[field.options])if(c.default!=null)row[c.fieldname]=c.default;(props.model[field.fieldname]??=[]).push(row)}
const inputType=f=>({Date:'date',Datetime:'datetime-local',Int:'number',Float:'number',Currency:'number',Percent:'number',Check:'checkbox'})[f.fieldtype]||'text'
</script>
<template><div class="schema-grid" :class="{child}"><template v-for="field in fields" :key="field.fieldname"><section v-if="field.fieldtype==='Table'" class="child-table"><div class="section-title"><h3>{{label(field.fieldname,field.label)}}</h3><UiButton v-if="!readonly&&!field.read_only" @click="add(field)">Thêm dòng</UiButton></div><div v-for="(row,index) in model[field.fieldname]||[]" :key="index" class="child-row"><strong>Dòng {{index+1}}</strong><SchemaForm :schema="{fields:schema.tables[field.options],tables:{}}" :model="row" :scope="scope" :readonly="readonly||!!field.read_only" child/><UiButton v-if="!readonly&&!field.read_only" @click="model[field.fieldname].splice(index,1)">Xóa dòng</UiButton></div><p v-if="!(model[field.fieldname]||[]).length" class="muted">Chưa có dòng.</p></section><label v-else :class="{'wide':field.fieldtype==='Code'||field.fieldtype==='Small Text'}"><span>{{label(field.fieldname,field.label)}} <small v-if="field.reqd&&!field.read_only">*</small></span><span v-if="readonly||field.read_only" class="field-value">{{model[field.fieldname]??'—'}}</span><textarea v-else-if="['Code','Small Text','Text','Long Text'].includes(field.fieldtype)" v-model="model[field.fieldname]" :required="!!field.reqd" rows="3"/><select v-else-if="field.fieldtype==='Select'" v-model="model[field.fieldname]" :required="!!field.reqd"><option value="">Chọn…</option><option v-for="option in (field.options||'').split('\n')" :key="option" :value="option">{{stateLabel(option)}}</option></select><input v-else-if="field.fieldtype==='Check'" :checked="model[field.fieldname]===true||Number(model[field.fieldname])===1" type="checkbox" @change="model[field.fieldname]=$event.target.checked?1:0"/><template v-else><input v-if="['Int','Float','Currency','Percent'].includes(field.fieldtype)" v-model.number="model[field.fieldname]" :type="inputType(field)" :step="field.fieldtype==='Int'?'1':'any'" :required="!!field.reqd"/><input v-else v-model="model[field.fieldname]" :type="inputType(field)" :required="!!field.reqd" :list="field.fieldtype==='Link'?'link-'+field.fieldname:undefined" @focus="options(field)" @input="options(field)"/><datalist v-if="field.fieldtype==='Link'" :id="'link-'+field.fieldname"><option v-for="option in links[field.fieldname]||[]" :key="option.value" :value="option.value">{{option.label}}</option></datalist></template><small v-if="field.description" class="muted">{{field.description}}</small></label></template></div></template>
